//! Advanced SIMD against the host: every case in `neon/cases.rs` (generated by
//! `tools/gen_neon_cases.py` with arm-none-eabi-as) is one A32 instruction, its T32
//! encoding, and an AArch64 snippet with the same lane semantics. On an AArch64 host the
//! snippet runs natively with FPCR.FZ and FPCR.DN set (ARMv7's Standard FPSCR value), and
//! the emulated A32 and T32 forms must produce the same registers, FPSCR.QC, memory and
//! writeback from random inputs. Elsewhere only the A32-vs-T32 comparison runs.
use arm_a32::{Cpu, MODE_SVC};
use emu_core::{Bus, Core, FlatRam};

#[allow(dead_code)]
struct Case {
    name: &'static str,
    a32: u32,
    t32: u32,
    /// D registers the instruction writes.
    dmask: u32,
    /// Core registers r0-r7 the instruction writes.
    rmask: u32,
    memory: bool,
    no_infinity: bool,
    #[cfg(target_arch = "aarch64")]
    host: unsafe extern "C" fn(*mut u64),
}

/// Host state: d0-d31 (= v0-v15), x0-x7, FPSR.
#[cfg(target_arch = "aarch64")]
const STATE: usize = 32 + 8 + 1;

#[cfg(target_arch = "aarch64")]
macro_rules! host_fn {
    ($asm:literal) => {{
        unsafe extern "C" fn f(state: *mut u64) {
            unsafe {
                core::arch::asm!(
                    "mrs x9, fpcr",
                    "mov x10, #0x3000000", // FZ | DN, round to nearest
                    "msr fpcr, x10",
                    "msr fpsr, xzr",
                    "ldp q0, q1, [x8]",
                    "ldp q2, q3, [x8, #32]",
                    "ldp q4, q5, [x8, #64]",
                    "ldp q6, q7, [x8, #96]",
                    "ldp q8, q9, [x8, #128]",
                    "ldp q10, q11, [x8, #160]",
                    "ldp q12, q13, [x8, #192]",
                    "ldp q14, q15, [x8, #224]",
                    "ldp x0, x1, [x8, #256]",
                    "ldp x2, x3, [x8, #272]",
                    "ldp x4, x5, [x8, #288]",
                    "ldp x6, x7, [x8, #304]",
                    $asm,
                    "stp q0, q1, [x8]",
                    "stp q2, q3, [x8, #32]",
                    "stp q4, q5, [x8, #64]",
                    "stp q6, q7, [x8, #96]",
                    "stp q8, q9, [x8, #128]",
                    "stp q10, q11, [x8, #160]",
                    "stp q12, q13, [x8, #192]",
                    "stp q14, q15, [x8, #224]",
                    "stp x0, x1, [x8, #256]",
                    "stp x2, x3, [x8, #272]",
                    "stp x4, x5, [x8, #288]",
                    "stp x6, x7, [x8, #304]",
                    "mrs x10, fpsr",
                    "str x10, [x8, #320]",
                    "msr fpcr, x9",
                    in("x8") state,
                    out("x0") _, out("x1") _, out("x2") _, out("x3") _,
                    out("x4") _, out("x5") _, out("x6") _, out("x7") _,
                    out("x9") _, out("x10") _,
                    out("v0") _, out("v1") _, out("v2") _, out("v3") _,
                    out("v4") _, out("v5") _, out("v6") _, out("v7") _,
                    out("v8") _, out("v9") _, out("v10") _, out("v11") _,
                    out("v12") _, out("v13") _, out("v14") _, out("v15") _,
                    out("v16") _, out("v17") _, out("v18") _, out("v19") _,
                    out("v20") _, out("v21") _, out("v22") _, out("v23") _,
                    out("v24") _, out("v25") _, out("v26") _, out("v27") _,
                    out("v28") _, out("v29") _, out("v30") _, out("v31") _,
                );
            }
        }
        f as unsafe extern "C" fn(*mut u64)
    }};
}

macro_rules! neon_cases {
    ($(($name:literal, $a32:literal, $t32:literal, $dmask:literal, $rmask:literal, $memory:literal, $noinf:literal, $host:literal)),* $(,)?) => {
        const CASES: &[Case] = &[$(Case {
            name: $name,
            a32: $a32,
            t32: $t32,
            dmask: $dmask,
            rmask: $rmask,
            memory: $memory,
            no_infinity: $noinf,
            #[cfg(target_arch = "aarch64")]
            host: host_fn!($host),
        }),*];
    };
}

include!("neon/cases.rs");

const A32_CODE: u64 = 0x1000;
const T32_CODE: u64 = 0x2000;
const BUFFER: u64 = 0x8000;
const BUFFER_LEN: usize = 256;
/// r0 for memory forms: 32-byte aligned, with room on both sides.
const BUFFER_OFFSET: usize = 64;
const QC: u32 = 1 << 27;

struct Rng(u64);

impl Rng {
    fn next(&mut self) -> u64 {
        self.0 ^= self.0 << 13;
        self.0 ^= self.0 >> 7;
        self.0 ^= self.0 << 17;
        self.0
    }

    fn pick<T: Copy>(&mut self, items: &[T]) -> T {
        items[self.next() as usize % items.len()]
    }

    /// A D register: random bits, or lanes of edge values for integers, floats and halves.
    fn word(&mut self) -> u64 {
        const F32: &[u32] = &[
            0, 0x8000_0000, 0x3f80_0000, 0xbf80_0000, 0x7f80_0000, 0xff80_0000, 0x7fc0_0000, 0x7f80_0001,
            0xffc0_0001, 0x0000_0001, 0x807f_ffff, 0x0080_0000, 0x8080_0001, 0x7f7f_ffff, 0x4000_0000,
            0x3f00_0000, 0x4f00_0000, 0xcf00_0000, 0x4f80_0000, 0x5f00_0000, 0x477f_e000, 0x477f_f000,
            0x3880_0000, 0x3380_0000, 0x337f_ffff, 0x4049_0fdb, 0x7e80_0000, 0x0100_0000, 0x3f7f_ffff,
        ];
        const F16: &[u16] = &[
            0, 0x8000, 0x3c00, 0xbc00, 0x7c00, 0xfc00, 0x7e00, 0x7c01, 0xfe01, 0x0001, 0x83ff, 0x0400,
            0x7bff, 0x3555, 0xc248,
        ];
        const I16: &[u16] = &[0, 1, 0x7fff, 0x8000, 0xffff, 0x8001, 0x00ff, 0xff00, 2, 0xfffe];
        const I32: &[u32] = &[0, 1, 0x7fff_ffff, 0x8000_0000, 0xffff_ffff, 0x8000_0001, 0xffff, 0x1_0000, 0x4000_0000];
        const I64: &[u64] = &[0, 1, u64::MAX, 0x7fff_ffff_ffff_ffff, 0x8000_0000_0000_0000, 0x8000_0000_0000_0001];
        match self.next() % 12 {
            0..=2 => self.next(),
            3 => (0..2).fold(0, |w, i| w | (self.pick(F32) as u64) << (32 * i)),
            4 | 5 => (0..2).fold(0, |w, i| {
                // ordinary floats around 1.0, sometimes near the flush threshold
                let exponent = if self.next() % 8 == 0 { self.next() % 6 } else { 112 + self.next() % 32 };
                let bits = (self.next() & 0x807f_ffff) | exponent << 23;
                w | (bits & 0xffff_ffff) << (32 * i)
            }),
            6 => (0..8).fold(0, |w, i| w | ((self.next() % 19) as i64 - 9) as u8 as u64 * (1 << (8 * i))),
            7 => (0..4).fold(0, |w, i| w | (self.pick(I16) as u64) << (16 * i)),
            8 => (0..2).fold(0, |w, i| w | (self.pick(I32) as u64) << (32 * i)),
            9 => self.pick(I64),
            10 => (0..4).fold(0, |w, i| w | (self.pick(F16) as u64) << (16 * i)),
            _ => self.next() & 0x0f0f_0f0f_0f0f_0f0f,
        }
    }
}

fn without_infinities(word: u64) -> u64 {
    let mut out = word;
    for i in 0..2 {
        let lane = (word >> (32 * i)) as u32;
        if lane & 0x7fff_ffff == 0x7f80_0000 {
            out = out & !(0xffff_ffffu64 << (32 * i)) | 0x3f80_0000u64 << (32 * i);
        }
    }
    out
}

struct Input {
    d: [u64; 32],
    r: [u32; 8],
    memory: Vec<u8>,
    fpscr: u32,
}

fn input(rng: &mut Rng, case: &Case) -> Input {
    let mut d = [0u64; 32];
    for w in d.iter_mut() {
        *w = rng.word();
        if case.no_infinity {
            *w = without_infinities(*w);
        }
    }
    let mut r = [0u32; 8];
    for x in r.iter_mut() {
        *x = rng.word() as u32;
    }
    if case.memory {
        r[0] = (BUFFER as usize + BUFFER_OFFSET) as u32;
        r[1] = (rng.next() % 96) as u32;
    }
    let memory = (0..BUFFER_LEN).map(|_| rng.next() as u8).collect();
    // NEON ignores FPSCR's controls: run with round-toward-zero, no flush, no default NaN.
    let fpscr = 3 << 22 | (rng.next() as u32 & 0xf000_0000);
    Input { d, r, memory, fpscr }
}

struct Outcome {
    d: [u64; 32],
    r: [u32; 8],
    qc: bool,
    memory: Vec<u8>,
}

fn emulate(ram: &mut FlatRam, word: u32, thumb: bool, input: &Input) -> Outcome {
    let mut cpu = Cpu::new();
    cpu.cpsr = MODE_SVC | 0xc0;
    cpu.cpacr = 0xf << 20;
    cpu.vfp.fpexc = 1 << 30;
    cpu.vfp.fpscr = input.fpscr;
    cpu.vfp.d = input.d;
    cpu.r[..8].copy_from_slice(&input.r);
    cpu.r[13] = 0x7000;
    ram.load(BUFFER, &input.memory).unwrap();
    if thumb {
        ram.write16(T32_CODE, (word >> 16) as u16).unwrap();
        ram.write16(T32_CODE + 2, word as u16).unwrap();
        cpu.r[15] = T32_CODE as u32;
        cpu.cpsr |= 1 << 5;
    } else {
        ram.write32(A32_CODE, word).unwrap();
        cpu.r[15] = A32_CODE as u32;
    }
    let result = cpu.step(ram);
    let expected_pc = if thumb { T32_CODE + 4 } else { A32_CODE + 4 };
    assert!(
        result.is_ok() && cpu.r[15] as u64 == expected_pc,
        "{:08x} ({}) did not execute: {result:?}, pc {:#x}",
        word,
        if thumb { "T32" } else { "A32" },
        cpu.r[15]
    );
    let mut memory = vec![0u8; BUFFER_LEN];
    for (i, byte) in memory.iter_mut().enumerate() {
        *byte = ram.read8(BUFFER + i as u64).unwrap();
    }
    let mut r = [0u32; 8];
    r.copy_from_slice(&cpu.r[..8]);
    Outcome { d: cpu.vfp.d, r, qc: cpu.vfp.fpscr & QC != 0, memory }
}

#[cfg(target_arch = "aarch64")]
fn compare(case: &Case, input: &Input, got: &Outcome, want: &Outcome) -> Option<String> {
    let mut problems = Vec::new();
    for i in 0..32 {
        let expected = if case.dmask >> i & 1 != 0 { want.d[i] } else { input.d[i] };
        if got.d[i] != expected {
            problems.push(format!("d{i} = {:016x}, expected {expected:016x}", got.d[i]));
        }
    }
    for i in 0..8 {
        let expected = if case.rmask >> i & 1 != 0 { want.r[i] } else { input.r[i] };
        if got.r[i] != expected {
            problems.push(format!("r{i} = {:08x}, expected {expected:08x}", got.r[i]));
        }
    }
    if got.qc != want.qc {
        problems.push(format!("QC = {}, expected {}", got.qc, want.qc));
    }
    if got.memory != want.memory {
        problems.push("memory differs".to_string());
    }
    if problems.is_empty() {
        return None;
    }
    let inputs: Vec<String> = (0..8).map(|i| format!("d{i}={:016x}", input.d[i])).collect();
    Some(format!("{}\n    inputs {} r0={:08x} r1={:08x}", problems.join("; "), inputs.join(" "), input.r[0], input.r[1]))
}

/// Run the AArch64 equivalent on the host.
#[cfg(target_arch = "aarch64")]
fn host(case: &Case, input: &Input) -> Outcome {
    let mut memory = input.memory.clone();
    let mut state = [0u64; STATE];
    state[..32].copy_from_slice(&input.d);
    for i in 0..8 {
        state[32 + i] = input.r[i] as u64;
    }
    let host_base = memory.as_mut_ptr() as u64 + BUFFER_OFFSET as u64;
    if case.memory {
        state[32] = host_base;
    }
    unsafe { (case.host)(state.as_mut_ptr()) };
    let mut d = [0u64; 32];
    d.copy_from_slice(&state[..32]);
    let mut r = [0u32; 8];
    for i in 0..8 {
        r[i] = state[32 + i] as u32;
    }
    if case.memory {
        // Writeback: the same displacement from the buffer as on the host.
        r[0] = (BUFFER as usize + BUFFER_OFFSET) as u32 + state[32].wrapping_sub(host_base) as u32;
    }
    Outcome { d, r, qc: state[40] & QC as u64 != 0, memory }
}

#[cfg(target_arch = "aarch64")]
const SEEDS: usize = 256;

#[cfg(target_arch = "aarch64")]
#[test]
fn neon_matches_host() {
    let mut ram = FlatRam::new(0, 0x10000);
    let mut rng = Rng(0x9e37_79b9_7f4a_7c15);
    let mut failures = Vec::new();
    let mut runs = 0;
    for case in CASES {
        for _ in 0..SEEDS {
            let input = input(&mut rng, case);
            let want = host(case, &input);
            let mut failed = false;
            for (thumb, word) in [(false, case.a32), (true, case.t32)] {
                let got = emulate(&mut ram, word, thumb, &input);
                runs += 1;
                if let Some(problem) = compare(case, &input, &got, &want) {
                    failures.push(format!("{} ({}): {problem}", case.name, if thumb { "T32" } else { "A32" }));
                    failed = true;
                    break;
                }
            }
            if failed {
                break;
            }
        }
    }
    eprintln!("{} cases, {runs} emulated runs compared with the host", CASES.len());
    assert!(failures.is_empty(), "{} of {} cases differ from the host:\n{}", failures.len(), CASES.len(), failures.join("\n"));
}

/// The T32 form of every case must do exactly what its A32 form does (runs on any host).
#[test]
fn t32_matches_a32() {
    let mut ram = FlatRam::new(0, 0x10000);
    let mut rng = Rng(0x2545_f491_4f6c_dd1d);
    let mut failures = Vec::new();
    for case in CASES {
        for _ in 0..32 {
            let input = input(&mut rng, case);
            let a32 = emulate(&mut ram, case.a32, false, &input);
            let t32 = emulate(&mut ram, case.t32, true, &input);
            if a32.d != t32.d || a32.r != t32.r || a32.qc != t32.qc || a32.memory != t32.memory {
                failures.push(case.name);
                break;
            }
        }
    }
    assert!(failures.is_empty(), "T32 and A32 differ: {failures:?}");
}
